"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3962],{3743(e){e.exports=JSON.parse('{"title":"\uc9c0\ub09c 3\uc8fc\uc758 \uc774\uc57c\uae30","date":"2025-09-30","coverUrl":"/kudzu-based-bench/assets/notion/1f032b25c4464025.png","html":"<h1 data-notion-block-id=\\"262e548d-8a8e-8080-804a-cc061cd0faa3\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"279e548d-8a8e-8030-adf0-c9f4223066ce\\" id=\\"279e548d-8a8e-8030-adf0-c9f4223066ce\\">\ube0c\ub77c\uc6b0\uc800 \ub3d9\uc791 \ud55c \ub208\uc5d0 \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://addyo.substack.com/p/how-modern-browsers-work\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://addyo.substack.com/p/how-modern-browsers-work</a><p data-notion-block-id=\\"279e548d-8a8e-802d-bbf6-c885f9d84aef\\"><a href=\\"https://developer.chrome.com/blog/inside-browser-part1\\">Inside the Browser</a>\uc640 \uac19\uc740 \uce5c\uc808\ud55c \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uc758 \ub3d9\uc791\uc744 \ud558\ub098\ub85c \ud569\uccd0\uc11c \uc124\uba85\ud574\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ubb3c\ub860 <a href=\\"https://ones-to-watch.ethansup.net/news/post/1c3e548d-8a8e-80a7-9539-cddcd66b5f38#1c9e548d-8a8e-800b-8cff-de429634e21b\\">TurboFan\uc758 TurboShaft \ubcc0\uacbd</a>\uac19\uc740 \ub9e4\uc6b0 \ucd5c\uc2e0 \uc815\ubcf4\ub098 <a href=\\"https://developer.chrome.com/docs/chromium/renderingng\\">\uc2e4\uc81c \ub80c\ub354\ub9c1\uc774 \uc774\ub8e8\uc5b4\uc9c0\ub294 RenderingNG</a>\ubcf4\ub2e4\ub294 \uac04\ub2e8\ud654\ud574\uc11c \uc54c\ub824\uc8fc\uc9c0\ub9cc, \uac1c\ubc1c\uc790\uc5d0\uac8c \uaf2d \ud544\uc694\ud55c \ube0c\ub77c\uc6b0\uc800 Speculative loading\uc774\ub098 \uc911\uc694\ud55c \ube0c\ub77c\uc6b0\uc800\uc758 \uc804\uccb4\uc801\uc778 \ub80c\ub354\ub9c1 \ubc29\uc2dd\uacfc \uc0dd\uc18c\ud55c \uac1c\ub150\uc778 Isolation \ubc29\uc2dd\uac19\uc740 \uac83\uc774\ub098 \ube0c\ub77c\uc6b0\uc800\uac04 \ucc28\uc774\ub97c \uc54c\ub824\uc8fc\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"279e548d-8a8e-8022-9f2e-d1f4b2ef40ab\\" id=\\"279e548d-8a8e-8022-9f2e-d1f4b2ef40ab\\">\uc560\ub2c8\uba54\uc774\uc158\uc740 \ud56d\uc0c1 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4.</h2><a href=\\"https://emilkowal.ski/ui/you-dont-need-animations\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://emilkowal.ski/ui/you-dont-need-animations</a><p data-notion-block-id=\\"279e548d-8a8e-8016-a4e8-d0b59801440d\\">\uc560\ub2c8\uba54\uc774\uc158\uc758 \ubaa9\uc801\uacfc \uc0ac\uc6a9\uc790 \uacbd\ud5d8\uc744 \uc5ee\uc5b4\uc11c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub2e4\ub978 \uae30\uc220 \uc124\uba85\uae00\uc5d0 \ube44\ud574\uc11c\ub294 \uac04\ub2e8\ud55c \uae00\uc774\uc9c0\ub9cc, \uc560\ub2c8\uba54\uc774\uc158\uc744 \ub123\uc744 \ub54c, \ud639\uc740 \uc778\ud130\ub809\uc158\uc744 \ub123\uc5b4\uc57c \ud560 \ub54c \uc6b0\ub9ac\uac00 \uc870\uc2ec\ud574\uc57c \ubd80\ubd84\uc744 \uc798 \uc9da\uc5b4\uc90d\ub2c8\ub2e4. \ubcf4\ud1b5 \uc560\ub2c8\uba54\uc774\uc158\uc758 \uc18d\ub3c4\uc5d0 \ub300\ud574 \uc2e0\uacbd\uc4f0\uc9c0 \uc54a\ub294\ub370, \uc560\ub2c8\uba54\uc774\uc158 \uc18d\ub3c4\ub098 \uc778\ud130\ub809\uc158 \uc18d\ub3c4\uc5d0 \ub300\ud574\uc11c\ub3c4 \ub2e4\uc2dc \uc0dd\uac01\ud574\ubcf4\uac8c \ub9cc\ub4e7\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"27be548d-8a8e-800d-b363-ceed9a4d4fb9\\" id=\\"27be548d-8a8e-800d-b363-ceed9a4d4fb9\\">Sanity\uc758 styled-components \ud0c8\ucd9c\uae30</h2><a href=\\"https://www.sanity.io/blog/cut-styled-components-into-pieces-this-is-our-last-resort\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.sanity.io/blog/cut-styled-components-into-pieces-this-is-our-last-resort</a><p data-notion-block-id=\\"27be548d-8a8e-8063-9b6e-cf8ee87ee343\\">Sanity\uac00 (\uc5b4\uca4c\uba74) \uac1c\ubc1c\uc790 \uc0c1\ub300 \uc11c\ube44\uc2a4\uc5ec\uc11c \uadf8\ub7f4 \uc218\ub3c4 \uc788\uc9c0\ub9cc, styled-components\uac00 \uad00\ub9ac \uc0c1\ud0dc\uc5d0 \ub4e4\uc5b4\uc11c\uace0 \uc0dd\uae34 \ubd88\ud3b8\ud568\uc744 \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c styled-components\ub97c \ud0c8\ucd9c\ud558\ub824\ub294 \uacc4\ud68d\uc744 \uc138\uc6b0\uace0 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud754\ud55c \uacbd\ud5d8\uc740 \uc544\ub2c8\uc9c0\ub9cc, \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc5c5\ub370\uc774\ud2b8\uac00 \ub418\uc9c0 \uc54a\ub294 \uacbd\uc6b0, \ub610\ub294 maintaining \ubaa8\ub4dc\uc5d0 \ub4e4\uc5b4\uac04 \uacbd\uc6b0 \uc0c8\ub85c\uc6b4 \ub300\ucc98 \ubc29\ubc95\uc744 \uc81c\uc2dc\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"27be548d-8a8e-8017-a474-e98c3e77a1cb\\" id=\\"27be548d-8a8e-8017-a474-e98c3e77a1cb\\">\ud328\ud0a4\uc9c0 \uad00\ub9ac\uc790\ub97c \ud1b5\ud55c \uc545\uc131\ucf54\ub4dc \ub300\ube44\ud558\uae30</h2><a href=\\"https://github.com/bodadotsh/npm-security-best-practices\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/bodadotsh/npm-security-best-practices</a><p data-notion-block-id=\\"27be548d-8a8e-80df-a38f-d78e68d3bf18\\"><a href=\\"https://tane.dev/2025/09/oh-no-not-again...-a-meditation-on-npm-supply-chain-attacks/\\">npm \uacf5\uae09\ub9dd \uacf5\uaca9</a>\uc774 \ub610 \uc77c\uc5b4\ub0ac\uc2b5\ub2c8\ub2e4. npm(\uacfc node.js\uc5d0 \uc5f0\uad00\ub41c \ubaa8\ub4e0 \ud328\ud0a4\uc9c0 \uad00\ub9ac\uc790\ub4e4)\uc744 \uc0ac\uc6a9\ud558\uac70\ub098 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ub9cc\ub4dc\ub294 \uacbd\uc6b0 \uc774\ub97c \ub300\ube44\ud560 \uc218 \uc788\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\ub294 \uae43\ud5c8\ube0c \ub808\ud3ec\uc9c0\ud1a0\ub9ac\uc785\ub2c8\ub2e4. \ubcf4\uc548\uc744 \uc704\ud574 \uc5b4\ub5a4 \uc870\uce58\ub97c \ucde8\ud574\uc57c\ud558\ub294\uc9c0 \uc0c1\uc138\ud558\uac8c \uc18c\uac1c\ud558\ubbc0\ub85c, \uaf2d \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"262e548d-8a8e-8011-9bd9-e03d40f8e4a6\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"279e548d-8a8e-80bc-bcfb-ea405e329206\\" id=\\"279e548d-8a8e-80bc-bcfb-ea405e329206\\">\ub9ac\uc561\ud2b8\uc5d0 \uc228\uaca8\uc9c4 \ube44\uc6a9</h2><a href=\\"https://www.lorenstew.art/blog/react-won-by-default/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.lorenstew.art/blog/react-won-by-default/</a><p data-notion-block-id=\\"279e548d-8a8e-80f5-a8db-f2aced85d2db\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud55c <a href=\\"https://infrequently.org/2024/11/if-not-react-then-what/\\">React\ub97c \uc120\ud0dd\ud558\uc9c0 \uc54a\ub294\ub2e4\uba74</a>\uacfc \ube44\uc2b7\ud558\uac8c \ub9ac\uc561\ud2b8\ub97c \uae30\ubcf8\uc73c\ub85c \uc120\ud0dd\ud558\ub294 \uac83\uc740 \uc228\uaca8\uc9c4 \ube44\uc6a9\uc774 \uc788\uc73c\uba70, \uc0dd\uac01\ubcf4\ub2e4 \ub2e4\ub978 \uac83\uc744 \uc120\ud0dd\ud558\ub294 \uac83\uc774 \uadf8\ub807\uac8c \ube44\uc6a9\uc774 \ub4e4\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc744 \uc54c\ub824\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"27be548d-8a8e-80b6-8f92-f41f507d4167\\" id=\\"27be548d-8a8e-80b6-8f92-f41f507d4167\\">JSON\uc774 \ud480\uc9c0 \ubabb\ud55c \ubb38\uc81c\ub4e4</h2><a href=\\"https://blog.dochia.dev/blog/json-isnt-json/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.dochia.dev/blog/json-isnt-json/</a><p data-notion-block-id=\\"27de548d-8a8e-8033-82a9-cd9db53a0f6b\\">JSON\uc740 \ub2e8\uc21c\ud558\uc9c0\ub9cc, \uadf8\ub807\uae30\uc5d0 \ub2e4\uc591\ud55c \uc5b8\uc5b4, \ud639\uc740 \ub3c4\uad6c\ub4e4\uc5d0\uc11c \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud558\uace0\ub294 \ud569\ub2c8\ub2e4. \uadf8\ub807\uae30\uc5d0, \ud30c\uc2f1\ud558\uae30 \uc804\uc5d0 \uc774 \uac12\uc774 \uc548\uc804\ud558\uac8c \ud30c\uc2f1\ub420 \uc218 \uc788\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uacfc\uc815\uc740 \ud544\uc694\ud574\ubcf4\uc774\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"279e548d-8a8e-8055-b28b-cb776876c881\\" id=\\"279e548d-8a8e-8055-b28b-cb776876c881\\">Tailwind\ub294 CSS-in-JS\ub2e4?</h2><a href=\\"https://nmn.sh/blog/2025-09-14-tailwind-is-css-in-js\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nmn.sh/blog/2025-09-14-tailwind-is-css-in-js</a><p data-notion-block-id=\\"27be548d-8a8e-8083-a4ce-e61a31958eaa\\">CSS-in-JS\ub77c\ub294 \uc6a9\uc5b4\uc758 \uc815\uc758\uc5d0 \ub300\ud55c \ud63c\ub780\uc2a4\ub7ec\uc6c0\uc744 \uc81c\uc2dc\ud558\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"279e548d-8a8e-8082-9f1d-ee0742189e7b\\" id=\\"279e548d-8a8e-8082-9f1d-ee0742189e7b\\">Bun\uc744 \uc815\ub9d0 \uc0ac\uc6a9\ud560\ub54c\uc778\uac00\uc694?</h2><a href=\\"https://dev.to/wojtekmaj/why-using-bun-in-production-maybe-isnt-the-best-idea-3deb\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://dev.to/wojtekmaj/why-using-bun-in-production-maybe-isnt-the-best-idea-3deb</a><h2 data-notion-block-id=\\"27be548d-8a8e-8093-9d76-e4edf191b1f7\\" id=\\"27be548d-8a8e-8093-9d76-e4edf191b1f7\\">Streaming Response\ub294 \ud37c\uc13c\ud2b8 \uce21\uc815\uc774 \uc5b4\ub835\ub2e4.</h2><a href=\\"https://jakearchibald.com/2025/fetch-streams-not-for-progress/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jakearchibald.com/2025/fetch-streams-not-for-progress/</a><p data-notion-block-id=\\"27be548d-8a8e-80e6-bd66-f15673bb29d9\\">fetch\ub97c \ud1b5\ud55c \uc5c5\ub85c\ub4dc/\ub2e4\uc6b4\ub85c\ub4dc \ud37c\uc13c\ud2b8 \uce21\uc815\uc774 \uc5b4\ub835\uace0, \uc815\ud655\ud558\uac8c \uce21\uc815\ud558\ub824\uba74 XHR\uc744 \uc0ac\uc6a9\ud574\uc57c \ud55c\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"27de548d-8a8e-8050-ad59-db1fa0bfe648\\" id=\\"27de548d-8a8e-8050-ad59-db1fa0bfe648\\">React Native \ucd5c\uc801\ud654\ud558\uae30</h2><a href=\\"https://engineering.usemotion.com/we-thought-react-native-was-the-answer-until-our-app-hit-190-cpu-f0e849073334\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://engineering.usemotion.com/we-thought-react-native-was-the-answer-until-our-app-hit-190-cpu-f0e849073334</a><p data-notion-block-id=\\"279e548d-8a8e-804a-b3f2-dffdd058ee60\\">\ub124\uc774\ud2f0\ube0c\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ud558\uae30 \uc804\uc5d0 \uc5b4\ub5bb\uac8c React Native\uc5d0 \uc788\ub294 \uc131\ub2a5 \ubb38\uc81c\ub97c \ucd5c\uc801\ud654\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"279e548d-8a8e-8057-8f42-c1ecbc81d489\\" id=\\"279e548d-8a8e-8057-8f42-c1ecbc81d489\\">CSS Layer\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ub3c4\uc804\uae30</h2><a href=\\"https://www.smashingmagazine.com/2025/09/integrating-css-cascade-layers-existing-project/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2025/09/integrating-css-cascade-layers-existing-project/</a><p data-notion-block-id=\\"27de548d-8a8e-80ea-bb65-d7e9e8b89002\\">CSS Layer\uc758 \uc6b0\uc120\uc21c\uc704\ub97c \uae30\ubc18\uc73c\ub85c \uc77c\ubc18 CSS\uc5d0\uc11c CSS Layer\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158\ud558\uba70 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"27de548d-8a8e-8037-ab80-dafd7c26de41\\" id=\\"27de548d-8a8e-8037-ab80-dafd7c26de41\\">\uc815\uc801 \ud398\uc774\uc9c0\uc5d0 \ucd94\ucc9c \uc2dc\uc2a4\ud15c \uc0bd\uc785\ud558\uae30</h2><a href=\\"https://netflixtechblog.com/unlocking-dynamic-pages-the-evolution-of-netflixs-client-server-graphql-apis-8b4631a59b39\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://netflixtechblog.com/unlocking-dynamic-pages-the-evolution-of-netflixs-client-server-graphql-apis-8b4631a59b39</a><p data-notion-block-id=\\"27de548d-8a8e-809d-a871-f12199f9c653\\">\uc815\uc801 \ud398\uc774\uc9c0\ub97c \ucd94\ucc9c \uc2dc\uc2a4\ud15c\uc774 \ud3ec\ud568\ub41c \ub3d9\uc801 \ud398\uc774\uc9c0\ub97c \uc5b4\ub5bb\uac8c \uc5c5\ub370\uc774\ud2b8\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. GraphQL\uc740 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \ud68c\uc0ac\uac00 \ub9ce\uc9c0\ub9cc, \ud398\uc774\uc9c0 \uc5c5\ub370\uc774\ud2b8\ub97c \uc124\uacc4\ud55c \uc544\uc774\ub514\uc5b4\ub294 \ub2e4\ub978 \uacf3\uc5d0 \uc801\uc6a9\ud560 \uc218 \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub985\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"262e548d-8a8e-80db-b5b2-d39d74a53848\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://github.com/facebook/react/pull/34374\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/facebook/react/pull/34374</a><p data-notion-block-id=\\"279e548d-8a8e-809b-822f-f34c6e811b57\\"><code>&#x3C;Activity /></code>\uac00 React canary\ubc84\uc804\uc5d0 \uc62c\ub77c\uc654\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://tanstack.com/blog/announcing-tanstack-start-v1\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tanstack.com/blog/announcing-tanstack-start-v1</a><p data-notion-block-id=\\"279e548d-8a8e-8029-a84f-d9c304aa2d6a\\">Tanstack Start\uac00 \ubc84\uc804 1\uc744 \uc900\ube44\ud558\uace0 \uc788\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://remix.run/blog/middleware\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://remix.run/blog/middleware</a><p data-notion-block-id=\\"279e548d-8a8e-80fb-b845-c9e8532e72ba\\">Middleware\uac00 React Router\uc5d0\uc11c \uc548\uc815\uc801\uc778 \uae30\ub2a5\uc73c\ub85c \ucd9c\uc2dc\ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://webassembly.org/news/2025-09-17-wasm-3.0/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://webassembly.org/news/2025-09-17-wasm-3.0/</a><p data-notion-block-id=\\"279e548d-8a8e-80bb-92a5-f6c8a25ab2c4\\">WASM 3.0 \ud45c\uc900\uc774 \uc0c8\ub86d\uac8c \ub4f1\uc7a5\ud588\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"27ae548d-8a8e-8000-bfa2-e205953cbbfe\\" id=\\"27ae548d-8a8e-8000-bfa2-e205953cbbfe\\">\ubc88\uc678: \uc6b0\ub9ac\ub294 \uc65c \ubcf5\uc7a1\ud55c \uc544\ud0a4\ud14d\uccd0\uc5d0 \ub04c\ub9b4\uae4c?</h2><a href=\\"https://kyrylo.org/software/2025/08/21/why-do-software-developers-love-complexity.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kyrylo.org/software/2025/08/21/why-do-software-developers-love-complexity.html</a><h2 data-notion-block-id=\\"27be548d-8a8e-805f-8a89-e6dced19f0bd\\" id=\\"27be548d-8a8e-805f-8a89-e6dced19f0bd\\">\ubc88\uc678: <code>bun install</code>\uc5d0\uc11c \ubb34\uc2a8 \uc77c\uc774 \uc77c\uc5b4\ub098\uae38\ub798 \ube60\ub97c\uae4c?</h2><a href=\\"https://bun.com/blog/behind-the-scenes-of-bun-install\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://bun.com/blog/behind-the-scenes-of-bun-install</a><p data-notion-block-id=\\"27de548d-8a8e-80c5-ba18-efa8a194e9ec\\">\ucee4\ub110\uacfc \uc2a4\ub808\ub4dc\u2026 \ucef4\ud4e8\ud130\uc5d0\uc11c \uc5b4\ub5a4 \uc77c\uc774 \uc77c\uc5b4\ub098\uae38\ub798 bun install\uc774 \ube60\ub97c\uae4c\ub97c \uc798 \uc124\uba85\ud574\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);